/**
 * Company-default pay plan for the Agent Pay Estimator.
 *
 * Every number here comes from the 2026 Agent Agreement (Schedule A, the
 * Monthly/Fast Start bonus pages, and Addendum I) or the New Hire
 * Compensation Package. Managers do not edit this file: the in-page
 * "Team setup" panel layers team overrides on top of these defaults and
 * encodes only the differences into the share link.
 *
 * Tier lists are [deals, bonus] pairs. Only the highest tier reached pays.
 */
(function (root) {
  'use strict';

  var PAY_DEFAULTS = {
    team: {
      name: 'Wholesale Payments',
      manager: '',
      note: 'I take it personally to make sure you hit your bonuses each month.',
      title: 'Team',
      // Who agents and recruits reach from the "Let's talk" tab. Blank until a
      // sales director fills in Team setup; the page hides contact UI meanwhile.
      contactName: '',
      contactTitle: 'Sales Director',
      contactPhone: '',
      contactEmail: ''
    },

    // Ramp-up = the first N months on the team (double commission + double bonus).
    rampMonths: 3,

    // Upfront commission per approved, processing deal (Addendum I "starting payment").
    upfront: { traditional: 300, cash: 400 },
    rampCommissionMultiplier: 2,

    // Agreement "Monthly Bonuses" page.
    monthlyTiers: [[5, 500], [8, 750], [10, 1000], [12, 1250], [15, 1750], [20, 2500]],
    // Ramp-up doubles the monthly bonus up to 10 deals only. Above that, ramp
    // reps fall back to the standard tiers when those pay more (see calc.effectiveTiers).
    rampTiers: [[5, 1000], [8, 1500], [10, 2000]],

    // New Hire package: 5 deals in the first 30 days.
    fastStart30: { deals: 5, bonus: 1000 },
    // 25 deals in the first 90 days; all 25 must reach minVolume when the report runs.
    signing: { deals: 25, bonus: 15000, minVolume: 5000 },

    // Addendum I "Statement Volume Tiers", paid per deal with a qualifying statement.
    statement: { lowMin: 20000, low: 75, midMin: 50000, mid: 200, topMin: 60000, topBase: 200, step: 10000, stepBonus: 100 },

    equipmentShare: 70,   // % of (sale price - equipment cost)
    closeRate: 20,        // % of company appointments expected to close

    residual: {
      share: 50,           // Schedule A residual share %
      firstPayMonth: 4,    // residuals start in month 4
      volume: 15000,       // example: avg monthly volume per merchant
      bps: 50,             // avg net margin per merchant, in basis points (manager setting, not shown to agents)
      attrition: 0         // % of merchants lost per month (manager setting, not shown to agents)
    },

    vesting: { months: 3, comp: 5000, accounts: 30 }
  };

  root.PAY_DEFAULTS = PAY_DEFAULTS;
  if (typeof module !== 'undefined' && module.exports) module.exports = PAY_DEFAULTS;
})(typeof window !== 'undefined' ? window : globalThis);
